require '../config/database.php';$adminPage=true;$pageTitle='Admin Dashboard';
$counts=[];foreach(['jobs','job_seekers','applications','categories'] as $table){$counts[$table]=$conn->query("SELECT COUNT(*) total FROM $table")->fetch_assoc()['total'];}
$rows=$conn->query('SELECT a.application_id,u.name,u.email,j.title,a.status,a.application_date FROM applications a JOIN users u ON u.user_id=a.seeker_id JOIN jobs j ON j.job_id=a.job_id ORDER BY a.application_id DESC');include '../includes/header.php';
?>
<section class="admin-hero"><div><small>ADMIN CONTROL CENTER</small><h1>Recruitment Dashboard</h1><p>Publish jobs, organize categories and make final candidate decisions from one place.</p></div><div class="admin-actions"><a href="jobs.php">＋ Add New Job</a><a href="../tracking.php">⌕ Track Result</a></div></section><section class="card admin-card"><h1>Application Decision Center</h1><?php if(isset($_GET['updated'])):?><div class="notice">Candidate result updated. The applicant can now view it using the Application ID.</div><?php endif;?><div class="stats"><?php foreach($counts as $name=>$count):?><div class="stat"><b><?=$count?></b><span><?=strtoupper(str_replace('_',' ',$name))?></span></div><?php endforeach;?></div><div class="table-wrap"><table><tr><th>Application ID</th><th>Candidate</th><th>Position</th><th>Status</th><th>Admin Decision</th><th>Candidate Output</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><strong>APP-<?=str_pad($r['application_id'],6,'0',STR_PAD_LEFT)?></strong></td><td><?=htmlspecialchars($r['name'])?><small class="table-sub"><?=htmlspecialchars($r['email'])?></small></td><td><?=htmlspecialchars($r['title'])?></td><td><span class="status <?=strtolower($r['status'])?>"><?=$r['status']==='Accepted'?'Selected':$r['status']?></span></td><td><form class="decision-form" method="post" action="update_status.php"><input type="hidden" name="application_id" value="<?=$r['application_id']?>"><select name="status"><option value="Pending" <?=$r['status']==='Pending'?'selected':''?>>Pending</option><option value="Shortlisted" <?=$r['status']==='Shortlisted'?'selected':''?>>Shortlisted</option><option value="Accepted" <?=$r['status']==='Accepted'?'selected':''?>>Selected</option><option value="Rejected" <?=$r['status']==='Rejected'?'selected':''?>>Rejected</option></select><button>Update Result</button></form></td><td><?php if($r['status']==='Accepted'):?><a class="mini-link" href="../appointment_letter.php?id=<?=$r['application_id']?>">Open Letter</a><?php elseif($r['status']==='Rejected'):?><span class="rejected-text">Rejected</span><?php else:?><span class="waiting-text">Waiting</span><?php endif;?></td></tr><?php endwhile;?></table></div></section>
